//! power.resource's functions: what the machine can do about its own
//! power, turning it off, and who is told when its power button is
//! pressed. A resource: no Open or Close, its first function in the first
//! slot. The base comes from OpenResource("power.resource").
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/power_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const exec = @import("../libs/exec/exec.zig");
const power = @import("../resources/power.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "power.resource";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const PowerAbilities = libraries.lvo(0);
    pub const PowerOff = libraries.lvo(1);
    pub const AddPowerNotify = libraries.lvo(2);
    pub const RemPowerNotify = libraries.lvo(3);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const PowerAbilities = *const fn (*PowerBase) callconv(.c) u32;
    pub const PowerOff = *const fn (*PowerBase) callconv(.c) void;
    pub const AddPowerNotify = *const fn (*PowerBase, *exec.Task, u32) callconv(.c) ?*power.PowerNotify;
    pub const RemPowerNotify = *const fn (*PowerBase, ?*power.PowerNotify) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const PowerBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *PowerBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// What this machine can do about its own power (POWERF_*); 0 where it
    /// can do nothing.
    pub fn PowerAbilities(self: *PowerBase) u32 {
        return libraries.call(self, LVO.PowerAbilities, Fn.PowerAbilities, .{});
    }

    /// The machine turned off. It returns only where that could not be done.
    pub fn PowerOff(self: *PowerBase) void {
        return libraries.call(self, LVO.PowerOff, Fn.PowerOff, .{});
    }

    /// `signals` sent to `task` when the machine's power button is pressed;
    /// null on a machine with no such button, or without memory.
    pub fn AddPowerNotify(self: *PowerBase, task: *exec.Task, signals: u32) ?*power.PowerNotify {
        return libraries.call(self, LVO.AddPowerNotify, Fn.AddPowerNotify, .{ task, signals });
    }

    /// No more of that.
    pub fn RemPowerNotify(self: *PowerBase, notify: ?*power.PowerNotify) void {
        return libraries.call(self, LVO.RemPowerNotify, Fn.RemPowerNotify, .{notify});
    }
};
